import numpy as np

eps = 0.05
p_b = np.array([1 - eps, eps])                 # p(b)
p_e = np.array([1 - eps, eps])                 # p(e)
p_a_given_be = np.zeros((2, 2, 2))             # p(a | b, e), 축 순서 b, e, a
for b in (0, 1):
    for e in (0, 1):
        for a in (0, 1):
            p_a_given_be[b, e, a] = 1.0 if a == (b or e) else 0.0

# 4단계: 결합 = 지역 조건부 확률의 곱
P_BEA = np.einsum("b,e,bea->bea", p_b, p_e, p_a_given_be)
for b in (0, 1):
    for e in (0, 1):
        for a in (0, 1):
            if P_BEA[b, e, a] > 0:
                print(f"b={b} e={e} a={a}  {P_BEA[b, e, a]:.4f}")
print("합 =", round(P_BEA.sum(), 6))
# A 를 모를 때 B, E 는 독립: P(B,E) = P(B)P(E)
print("독립?", np.allclose(P_BEA.sum(axis=2), np.outer(p_b, p_e)))
